// Constants -------------------------------------------------------------------
const WORD_SEPARATOR_PATTERN = /[\s-]+/

// API -------------------------------------------------------------------------
/** Normalize input text into a trimmed lowercase hyphen-separated slug. */
export function normalizeSlug(input: string): string {
  return input
    .trim()
    .toLowerCase()
    .split(WORD_SEPARATOR_PATTERN)
    .filter(Boolean)
    .join('-')
}

