import { describe, expect, test } from 'bun:test'
import { normalizeSlug } from './slug.js'

// Constants -------------------------------------------------------------------
const BLANK_OR_SEPARATOR_INPUTS = ['', '   ', '---', '  --  -  ']

// Tests -----------------------------------------------------------------------
describe('given normalizeSlug', () => {
  test('when input is empty or contains only spaces and hyphens, then it returns an empty string', () => {
    for (const candidate of BLANK_OR_SEPARATOR_INPUTS) {
      expect(normalizeSlug(candidate)).toBe('')
    }
  })

  test('when input has surrounding spaces and uppercase letters, then it returns trimmed lowercase hyphenated words', () => {
    expect(normalizeSlug('  Hello-World  ')).toBe('hello-world')
  })

  test('when words have repeated spaces or hyphens, then it collapses separators into single hyphens', () => {
    expect(normalizeSlug('  Foo - Bar -- Baz  ')).toBe('foo-bar-baz')
  })
})
